#!/usr/bin/env bash
# Copyright (c) PRO-Robotech
# SPDX-License-Identifier: BUSL-1.1
#
# security-txt-render-test.sh — рендер карты security.txt детерминирован по входу
# и несёт ровно одно поле Expires в форме UTC (kacho#2876).
#
# Прежде шаблон писал `Expires` и строку «Generated by helm at» моментом рендера:
# каждый upgrade давал дифф карты при неизменном входе, а `Expires` истекал в ту
# секунду, в которую файл выкатывался. Что объявленные величины годны (позже
# выпуска, не дальше года, не истекают в ближайший запас), судит
# deploy/security_txt_expires_test.go по объявлению; здесь — то, что видно
# только в рендере: два рендера каждой цепочки deploy/stacks.txt побайтно равны,
# и поле в них одно и в форме UTC.
#
# Способность упасть — на настоящем рендере: (И1) подмена одного документа
# моментом рендера (так выглядел прежний шаблон) обязана дать неравенство;
# (И2) рендер без поля Expires обязан дать находку; близнец — сам рендер дерева.
#
# Коды: 0 зелено · 1 находка о дереве · 2 условие не создано (outcome.sh).
set -uo pipefail
. "$(dirname "$0")/stacks.sh"

HERE="$(cd "$(dirname "$0")" && pwd)"
DEPLOY="$(cd "$HERE/../.." && pwd)"
UMBRELLA="$DEPLOY/helm/umbrella"
# shellcheck source=deploy/tests/helm/outcome.sh
. "$HERE/outcome.sh"
require_helm
require_python_yaml

STACKS="$(stacks_table | cut -d: -f1)" || fatal "таблица стенда не прочитана"
STACKS_N="$(printf '%s\n' "$STACKS" | grep -c .)"
EXPECTED_ASSERTIONS=$((STACKS_N + 2))
WORK="$(mktemp -d)"; trap 'rm -rf "$WORK"' EXIT

# card <файл рендера> — карта kacho-security-txt: её metadata, затем текст файла
# как есть (пусто — карты нет).
card() {
  python3 - "$1" <<'PY'
import sys, yaml
for d in yaml.safe_load_all(open(sys.argv[1])):
    if isinstance(d, dict) and d.get("kind") == "ConfigMap" and (d.get("metadata") or {}).get("name") == "kacho-security-txt":
        meta = dict(d.get("metadata") or {})
        print(yaml.safe_dump(meta, sort_keys=True), end="")
        print("---")
        print((d.get("data") or {}).get("security.txt", ""), end="")
PY
}
# expires_ok <карта> — ровно одно поле Expires, UTC в форме RFC 3339.
expires_ok() {
  [ "$(grep -cE '^[[:space:]]*Expires:' "$1")" -eq 1 ] &&
    grep -qE '^[[:space:]]*Expires: [0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}Z$' "$1"
}

judged=0
for s in $STACKS; do
  args="$(stacks_args "$s" "$UMBRELLA")" || fatal "цепочка $s не прочитана"
  for i in 1 2; do
    # shellcheck disable=SC2086
    helm_try kacho-umbrella "$UMBRELLA" -n kacho $args
    render_nonempty_or_fatal "цепочка $s, рендер $i"
    printf '%s\n' "$HELM_OUT" > "$WORK/$s.$i.yaml"
    card "$WORK/$s.$i.yaml" > "$WORK/$s.$i.card" || fatal "рендер цепочки $s не разобран"
  done
  if [ ! -s "$WORK/$s.1.card" ]; then
    echo "  $s: карты security.txt нет (выключено) — законный близнец"; ok; continue
  fi
  judged=$((judged + 1))
  a="$(sha256sum < "$WORK/$s.1.card" | cut -c1-12)"; b="$(sha256sum < "$WORK/$s.2.card" | cut -c1-12)"
  if [ "$a" != "$b" ]; then violation "$s: два рендера подряд дали разные карты security.txt ($a… ≠ $b…) — рендер зависит не только от входа"
  elif ! expires_ok "$WORK/$s.1.card"; then violation "$s: в карте не ровно одно поле Expires в форме UTC (YYYY-MM-DDTHH:MM:SSZ)"
  else echo "  $s: два рендера равны (sha256 $a…), Expires один, UTC"; fi
  ok
done
[ "$judged" -gt 0 ] || violation "ни в одной цепочке карты security.txt нет — обход пуст"

# ── Инъекции на настоящем рендере ───────────────────────────────────────────
s1="$(printf '%s\n' "$STACKS" | head -1)"
c="$WORK/$s1.1.card"
if [ -s "$c" ]; then
  sed -E "s/^([[:space:]]*Expires: ).*/\1$(date +%Y-%m-%dT%H:%M:%S.%NZ)/" "$c" > "$WORK/inj1"
  if cmp -s "$c" "$WORK/inj1"; then violation "И1: подмена моментом рендера не изменила карту — проба упасть не может"
  else echo "  И1: карта с моментом рендера ≠ карта дерева — неравенство видно"; fi
  ok
  grep -vE '^[[:space:]]*Expires:' "$c" > "$WORK/inj2"
  if expires_ok "$WORK/inj2"; then violation "И2: карта без Expires прошла — проба поля упасть не может"
  else echo "  И2: карта без Expires — находка"; fi
  ok
else
  violation "у цепочки $s1 карты нет — инъекциям не во что встать"; ok; ok
fi

outcome_verdict "цепочек $STACKS_N, карт судимо $judged"
